import{_ as e,c as a,o as t,f as r}from"./chunks/framework.BOAZPCR7.js";const f=JSON.parse('{"title":"Near real-time data on the human neutralizing antibody landscape to influenza virus in summer of 2026 and the G155E mutation","description":"","frontmatter":{"layout":"post","title":"Near real-time data on the human neutralizing antibody landscape to influenza virus in summer of 2026 and the G155E mutation","date":"2026-09-16T00:00:00.000Z","author":"Jesse Bloom","head":[["link",{"rel":"canonical","href":"https://jbloomlab.org/posts/2026-09-16_kikawa.html"}]]},"headers":[],"relativePath":"posts/2026-09-16_kikawa.md","filePath":"posts/2026-09-16_kikawa.md"}'),n={name:"posts/2026-09-16_kikawa.md"},o=r('<p>Today we posted a <a href="https://doi.org/10.64898/2026.09.15.751855" target="_blank" rel="noreferrer">preprint</a> describing work led by Caroline Kikawa and Andrew Butler using sequencing-based neutralization assays to characterize the human neutralizing antibody landscape to influenza virus. Our results underscore the impact of the H1N1 HA mutation G155E on a subset of the human population.</p><hr><p>This preprint is the third installation in our efforts to use sequencing-based neutralization assays to characterize the human neutralization antibody landscape in near real time to inform vaccine strain selection.</p><p>We found that certain strains had reduced neutralization by human sera, with the most profound effect that the G155E mutation in H1N1 HA reduced neutralization especially by sera from younger individuals.</p><p>For summaries of the study, see:</p><ul><li><a href="https://bsky.app/profile/jbloomlab.bsky.social/post/3mvpr2daio22v" target="_blank" rel="noreferrer">Bluesky thread</a>, more easily read <a href="https://skywriter.blue/@jbloomlab.bsky.social/3mvpr2daio22v" target="_blank" rel="noreferrer">in threaded form here</a></li><li><a href="https://x.com/jbloom_lab/status/2100580517565665661" target="_blank" rel="noreferrer">X thread</a></li><li><a href="https://slides.com/jbloom/options2026" target="_blank" rel="noreferrer">Slides presented at the Options for Control of Influenza meeting</a></li></ul><p>See <a href="https://jbloomlab.github.io/flu-seqneut-2026/summary.html" target="_blank" rel="noreferrer">https://jbloomlab.github.io/flu-seqneut-2026/summary.html</a> for an interactive summary of the results and links to all raw data.</p><h2 id="postscript" tabindex="-1">Postscript <a class="header-anchor" href="#postscript" aria-label="Permalink to &quot;Postscript&quot;">​</a></h2><p>A finding of our study was that the emerging G155E mutation in H1N1 caused a strong reduction in neutralization especially among young adults.</p><p>So far (as of October 2026), it appears to be an early H1N1 dominated season with a lot of H1N1, see:</p><ul><li><a href="https://www.nature.com/articles/d41586-026-03150-8" target="_blank" rel="noreferrer">Nature News article</a></li><li><a href="https://lnkd.in/p/gDEVwA8D" target="_blank" rel="noreferrer">Alex Greninger&#39;s LinkedIn post</a></li><li><a href="https://www.celinegounder.com/p/mrna-flu-shot-mflusiva-flu-season-2026" target="_blank" rel="noreferrer">Celine Gounder blog post</a></li></ul>',11),i=[o];function s(l,u,h,p,d,m){return t(),a("div",null,i)}const b=e(n,[["render",s]]);export{f as __pageData,b as default};
